// The cards of the Insights page. Each card is one claim about how much of Formula 1 results belongs to the driver and how much to the car:
// a headline written from the data (the few facts written by hand are asserted in tests/test-insights.mjs), one chart, and a note on how it was computed and where it can mislead.
// `label` is a short name for the list of slides beside the card (30 characters at most).
// The numbers come from site/js/insights-data.js, generated by packages/research/python/compute-findings.py.
//
// `kind` is how much weight a claim can carry: 'direct' is counted from the results with no rating involved, 'model' uses the ratings
// (and so depends on how they split a team's result between driver and car).
import {
  average,
  drawAxes,
  drawHorizontalBars,
  drawLines,
  drawScatter,
  drawText,
  createSvgElement,
  formatInteger,
  formatOneDecimal,
  formatSigned,
  horizontalBarsHeight,
  legendHtml,
  mountChart,
  surname,
  tableHtml,
} from './insights-charts.js';

const chartIn = (root, name) => root.querySelector(`[data-chart="${name}"]`);

const CIRCUIT_LABELS = [
  ['Marina Bay', 'Singapore'],
  ['Hermanos Rodríguez', 'Mexico City'],
  ['Albert Park', 'Melbourne'],
  ['José Carlos Pace', 'Interlagos'],
  ['Yas Marina', 'Abu Dhabi'],
  ['Sepang', 'Sepang'],
  ['Bahrain', 'Bahrain'],
  ['Villeneuve', 'Montréal'],
  ['Americas', 'Austin'],
  ['Catalunya', 'Barcelona'],
  ['Spa-Francorchamps', 'Spa'],
  ['Enzo e Dino Ferrari', 'Imola'],
  ['Monza', 'Monza'],
  ['Baku', 'Baku'],
  ['Shanghai', 'Shanghai'],
  ['Monaco', 'Monaco'],
];
const circuitLabel = (name) => (CIRCUIT_LABELS.find(([fragment]) => name.includes(fragment)) || [null, name.replace(' Circuit', '')])[1];
const findCircuit = (rows, label) => rows.find((row) => circuitLabel(row.name) === label);

const pearson = (xs, ys) => {
  const meanX = average(xs);
  const meanY = average(ys);
  let covariance = 0;
  let varianceX = 0;
  let varianceY = 0;
  xs.forEach((x, index) => {
    covariance += (x - meanX) * (ys[index] - meanY);
    varianceX += (x - meanX) ** 2;
    varianceY += (ys[index] - meanY) ** 2;
  });
  return covariance / Math.sqrt(varianceX * varianceY);
};

